class Main {
    public static void main(String[] args) {
        Account a = new Account();
        a.deposit(30);
        System.out.println(a.getBalance());
    }
}
class Account {
    private int balance;
    public boolean deposit(int amount) {
        if (amount <= 0) {
            return false;
        }
        balance += amount;
        return true;
    }
    public int getBalance() {
        return balance;
    }
}

